"""Write docs/messages.md: every message kind in English and Tamil, for wording review (the Tamil needs a native speaker).

Usage: python scripts/render_sample_messages.py
"""
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(root / "backend"))
from safarset.notify.render import load_templates, render, sms_stats  # noqa: E402
from safarset.notify.samples import samples  # noqa: E402


def build():
    lines = ["# SMS message samples (EN + TA)", "",
             "Generated by `scripts/render_sample_messages.py` from `backend/safarset/notify/templates/{en,ta}.json`; a test keeps this file in sync.",
             "", f"* English: {load_templates('en')['review_status']}", f"* Tamil: **{load_templates('ta')['review_status']}**", "",
             "Every journey message names the vehicle, where to board, the times, the destination and the group size, followed by the reason.",
             "The reason is generated from the allocation's machine-readable reason, so both languages explain the same decision.",
             "SMS cost: Tamil is sent as UCS-2 (70 characters per segment, 67 when joined); English is GSM-7 (160 / 153).", ""]
    for title, group, alloc, kind, ctx in samples():
        text, reason, lang = render(group, alloc, kind, ctx, group["attrs"]["language"])
        s = sms_stats(text)
        lines += [f"## {title}", "", f"`{kind}` / {lang} / {s['chars']} characters, {s['encoding']}, {s['segments']} segment(s)", "", f"> {text}", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    out = root / "docs" / "messages.md"
    out.write_text(build() + "\n", encoding="utf-8")
    print(f"wrote {out}")
